// Actual recorded water Foley by RomanKolachnik, CC0 1.0, Freesound Water Footsteps.
// Source URLs, download hashes and processing are in WATER_AUDIO_CREDITS.md.
// Embedded mono PCM avoids new requests, asynchronous decoding and codec differences.
const RS_WATER_RECORDINGS=Object.freeze([
{id:672202,sampleRate:24000,data:""},
{id:672201,sampleRate:24000,data:""},
{id:672200,sampleRate:24000,data:""},
{id:672199,sampleRate:24000,data:""},
{id:672205,sampleRate:24000,data:""},
{id:672204,sampleRate:24000,data:""}
]);
const RS_WATER_DECODED=[];
function rsWaterRecording(take=0){
 const index=((Math.floor(take)%RS_WATER_RECORDINGS.length)+RS_WATER_RECORDINGS.length)%RS_WATER_RECORDINGS.length;
 if(RS_WATER_DECODED[index])return RS_WATER_DECODED[index];
 const item=RS_WATER_RECORDINGS[index],alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/',text=item.data;
 const bytes=new Uint8Array(Math.floor(text.length*3/4)-(text.endsWith('==')?2:text.endsWith('=')?1:0));
 let at=0;
 for(let i=0;i<text.length;i+=4){const a=alphabet.indexOf(text[i]),b=alphabet.indexOf(text[i+1]),c=alphabet.indexOf(text[i+2]),d=alphabet.indexOf(text[i+3]);
  if(at<bytes.length)bytes[at++]=(a<<2)|(b>>4);if(at<bytes.length)bytes[at++]=((b&15)<<4)|(c>>2);if(at<bytes.length)bytes[at++]=((c&3)<<6)|d;
 }
 const data=new Float32Array(bytes.length/2);for(let i=0;i<data.length;i++){let n=bytes[i*2]|bytes[i*2+1]<<8;if(n&32768)n-=65536;data[i]=n/32768;}
 return RS_WATER_DECODED[index]={id:item.id,sampleRate:item.sampleRate,data};
}
